-- =====================================================
-- RPAD - Notas Digitales: carga inicial de "Qué se solicita" de cada dataset
-- =====================================================
-- Spec: docs/superpowers/specs/2026-10-12-notas-digitales-design.md (sección 7.6)
-- Textos redactados a partir de la descripción, la API del portal y las columnas de los archivos publicados,
-- y aprobados por el Director de Datos Públicos y Comunicación el 14/10/2026.
-- Requiere migracion-que-se-solicita.sql (la columna). Es la única carga que no pasa por la doble
-- verificación, porque inicializa un campo nuevo; después cada cambio se propone y se aprueba en RPAD.
-- Solo completa los datasets que todavía no tienen texto: no pisa un cambio ya aprobado en RPAD.
-- Ejecutar: mysql -u USUARIO -p NOMBRE_BASE < migracion-que-se-solicita-datos.sql
-- =====================================================

SET NAMES utf8mb4;

-- 1. Presupuesto Municipal
UPDATE datasets SET que_se_solicita = 'Presupuesto de gastos aprobado para el nuevo ejercicio (el año siguiente al último publicado), una fila por jurisdicción (Poder Ejecutivo, Concejo Deliberante y Tribunal de Cuentas) y tipo de gasto según partida principal, con el monto asignado en pesos. Remitir en planilla editable (Excel o CSV) con las mismas columnas del archivo publicado.' WHERE id = 1 AND que_se_solicita IS NULL;
-- 2. Gasto Público
UPDATE datasets SET que_se_solicita = 'Ejecución del gasto municipal del nuevo período (el semestre siguiente al último publicado), una fila por secretaría y subpartida, con partida principal, partida y subpartida presupuestaria, monto presupuestado y monto devengado en pesos. Remitir en planilla editable (Excel o CSV) con las mismas columnas del archivo publicado.' WHERE id = 2 AND que_se_solicita IS NULL;
-- 3. Funcionarios Públicos
UPDATE datasets SET que_se_solicita = 'Nómina actualizada de funcionarios de planta política (intendente, secretarios, subsecretarios, coordinadores, asesores y demás cargos) a la fecha de corte del nuevo período, una fila por persona, con apellido y nombre, sector, secretaría, tipo de planta y cargo. Remitir en planilla editable (Excel o CSV) con las mismas columnas del archivo publicado.' WHERE id = 3 AND que_se_solicita IS NULL;
