UPDATE datasets SET que_se_solicita = 'Datos mensuales de castraciones quirúrgicas realizadas por el servicio veterinario municipal en el nuevo período (el año siguiente al último publicado), una fila por mes, especie (canino o felino) y sexo (macho o hembra), con la cantidad de castraciones. Remitir en planilla editable (Excel o CSV) con las mismas columnas del archivo publicado.' WHERE id = 4 AND que_se_solicita IS NULL;
